/// Fast-path filter for the bare Kernel method dispatch.
/// Most no-receiver calls are user methods, so we only try the eager Kernel overload path for names that actually live on Kernel / BasicObject / Comparable as `self?.` style module functions (Integer / rand / sleep / ...).
fn is_known_kernel_bare_method(name: &str) -> bool {
    matches!(
        name,
        "Array"
            | "Complex"
            | "Float"
            | "Hash"
            | "Integer"
            | "Rational"
            | "String"
            | "abort"
            | "at_exit"
            | "autoload"
            | "autoload?"
            | "binding"
            | "callcc"
            | "caller"
            | "caller_locations"
            | "catch"
            | "chomp"
            | "chop"
            | "eval"
            | "exec"
            | "exit"
            | "exit!"
            | "fail"
            | "fork"
            | "format"
            | "gets"
            | "global_variables"
            | "gsub"
            | "lambda"
            | "load"
            | "local_variables"
            | "loop"
            | "open"
            | "p"
            | "pp"
            | "print"
            | "printf"
            | "proc"
            | "putc"
            | "puts"
            | "raise"
            | "rand"
            | "readline"
            | "readlines"
            | "require"
            | "require_relative"
            | "select"
            | "set_trace_func"
            | "sleep"
            | "spawn"
            | "sprintf"
            | "srand"
            | "sub"
            | "syscall"
            | "system"
            | "test"
            | "throw"
            | "trace_var"
            | "trap"
            | "untrace_var"
            | "warn"
            | "__dir__"
            | "__method__"
            | "__callee__"
            | "block_given?"
            | "frozen?"
            | "instance_of?"
            | "is_a?"
            | "kind_of?"
            | "method"
            | "methods"
            | "nil?"
            | "object_id"
            | "public_method"
            | "public_methods"
            | "private_methods"
            | "protected_methods"
            | "respond_to?"
            | "tap"
            | "then"
            | "to_s"
            | "yield_self"
    )
}

thread_local! {
    static LINE_START_INDEX: std::cell::RefCell<(usize, usize, u64, Vec<u32>)> =
        const { std::cell::RefCell::new((0, 0, 0, Vec::new())) };
}

fn line_index_sample_hash(source: &[u8]) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut hasher = rustc_hash::FxHasher::default();
    source.len().hash(&mut hasher);
    let take = source.len().min(64);
    source[..take].hash(&mut hasher);
    source[source.len() - take..].hash(&mut hasher);
    let mid = source.len() / 2;
    source[mid..(mid + take).min(source.len())].hash(&mut hasher);
    hasher.finish()
}

thread_local! {
    static INFER_NODE_DEPTH: std::cell::Cell<u32> = const { std::cell::Cell::new(0) };
    static INFER_NODE_FUEL: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
    static INFER_NODE_FUEL_BUDGET: std::cell::Cell<u64> =
        const { std::cell::Cell::new(DEFAULT_INFER_NODE_FUEL_BUDGET) };
}

/// Recursion depth cap for `infer_node_type*`. A conservative value that's safe even for the
/// smallest stack (wasm's ~1MiB linear stack); real code's expression nesting falls far short of this.
const MAX_INFER_NODE_DEPTH: u32 = 100;
const MIN_INFER_NODE_FUEL_BUDGET: u64 = 100_000;
const INFER_NODE_FUEL_PER_SOURCE_BYTE: u64 = 20;
const DEFAULT_INFER_NODE_FUEL_BUDGET: u64 = 1_500_000;

pub fn set_infer_node_fuel_budget(source_len: usize) {
    let budget =
        MIN_INFER_NODE_FUEL_BUDGET.max(source_len as u64 * INFER_NODE_FUEL_PER_SOURCE_BYTE);
    INFER_NODE_FUEL_BUDGET.with(|cell| cell.set(budget));
}

struct InferNodeGuard;

impl InferNodeGuard {
    fn enter() -> Option<Self> {
        let depth_ok = INFER_NODE_DEPTH.with(|depth| {
            let current = depth.get();
            if current == 0 {
                INFER_NODE_FUEL
                    .with(|fuel| fuel.set(INFER_NODE_FUEL_BUDGET.with(std::cell::Cell::get)));
            }
            if current >= MAX_INFER_NODE_DEPTH {
                return false;
            }
            depth.set(current + 1);
            true
        });
        if !depth_ok {
            return None;
        }
        let fuel_ok = INFER_NODE_FUEL.with(|fuel| {
            let remaining = fuel.get();
            if remaining == 0 {
                false
            } else {
                fuel.set(remaining - 1);
                true
            }
        });
        if !fuel_ok {
            INFER_NODE_DEPTH.with(|depth| depth.set(depth.get().saturating_sub(1)));
            return None;
        }
        Some(Self)
    }
}

impl Drop for InferNodeGuard {
    fn drop(&mut self) {
        INFER_NODE_DEPTH.with(|depth| depth.set(depth.get().saturating_sub(1)));
    }
}

fn offset_to_location(source: &[u8], offset: usize) -> SourceLocation {
    let clamped = offset.min(source.len());
    LINE_START_INDEX.with(|cell| {
        let mut slot = cell.borrow_mut();
        let key = (
            source.as_ptr() as usize,
            source.len(),
            line_index_sample_hash(source),
        );
        if (slot.0, slot.1, slot.2) != key {
            let mut starts: Vec<u32> = Vec::with_capacity(source.len() / 24 + 1);
            starts.push(0);
            for (idx, &byte) in source.iter().enumerate() {
                if byte == b'\n' {
                    starts.push((idx + 1) as u32);
                }
            }
            *slot = (key.0, key.1, key.2, starts);
        }
        let starts = &slot.3;
        let line_idx = starts.partition_point(|&start| start as usize <= clamped) - 1;
        SourceLocation {
            line: (line_idx + 1) as u32,
            column: (clamped - starts[line_idx] as usize) as u32,
        }
    })
}

fn offset_to_location_from(
    source: &[u8],
    _base_offset: usize,
    _base_loc: SourceLocation,
    offset: usize,
) -> SourceLocation {
    offset_to_location(source, offset)
}

