    fn ensure_stdlib_class(&mut self, class_name: &str) {
        if let Some(loader) = self.lazy_loader {
            for stdlib_class in [class_name, "Kernel"] {
                if self.merged_stdlib_classes.contains(stdlib_class) {
                    continue;
                }
                self.merged_stdlib_classes.insert(stdlib_class.to_string());
                if loader.merge_class_into(stdlib_class, &mut self.registry) {
                    continue;
                }
                if let Some((head, _)) = stdlib_class.split_once("::")
                    && loader.is_loadable_namespace_head(head)
                    && self.merged_stdlib_classes.insert(head.to_string())
                {
                    loader.merge_class_into(head, &mut self.registry);
                }
            }
        }
    }

    fn ensure_external_class(&mut self, class_name: &str) {
        // Absolute references (`include ::Foo`, `class X < ::Bar`) carry a leading `::` that is not part of the stored registry / external key, so normalize before lookup — otherwise the external class (and its nested `ClassMethods`) never merges in the lazy per-file path.
        let class_name = class_name.trim_scope_prefix();
        if self.merged_external_classes.contains(class_name) {
            return;
        }
        if self.suppress_external_merge {
            return;
        }
        let mut merged = false;
        if let Some(external_rbs) = self.external_rbs
            && external_rbs
                .class_data_for(class_name)
                .is_some_and(ClassData::has_type_substance)
        {
            self.registry.merge_rbs_class_from(external_rbs, class_name);
            merged = true;
        }

        // Generated declarations (`sorbet/rbi/`) compose with the source definition rather than being shadowed by it: a project class defined in Ruby can still owe part of its surface to tapioca dsl RBI (schema attributes, scopes), exactly as Sorbet composes source with RBI.
        // The merge is additive — an existing method variant wins over the RBI one — so source stays authoritative.
        if let (Some(lazy_rbi_loader), Some(stdlib_loader)) =
            (self.lazy_rbi_loader, self.lazy_loader)
        {
            merged =
                lazy_rbi_loader.merge_class_into(class_name, &mut self.registry, stdlib_loader)
                    || merged;
        }

        if !merged {
            if Self::is_sorbet_runtime_module(class_name) && !self.registry.has_class(class_name) {
                self.synthesize_sorbet_runtime_module(class_name);
            }
            self.merged_external_classes.insert(class_name.to_string());
            return;
        }

        self.merged_external_classes.insert(class_name.to_string());

        let Some(class_data) = self.registry.class_data_for(class_name) else {
            return;
        };
        let superclass = class_data.superclass.clone();
        let mixins = class_data.mixins.clone();

        if let Some(superclass) = superclass {
            self.ensure_external_class_in_scope(class_name, &superclass);
        }
        for mixin in mixins {
            self.ensure_external_class_in_scope(class_name, &mixin.module_name);
        }
        // By the `include M` convention, `M::ClassMethods` can be resolved as the includer's class methods, so once the module itself is merged, also explicitly load the nested `ClassMethods`. The gem's actual implementation does `base.extend(ClassMethods)` in a `self.included` hook (Concern just formalizes this), but a tapioca-generated RBI strips the body, so that hook edge isn't visible statically.
        // ClassMethods is a nested constant, not a mixin edge, so it needs to be loaded separately.
        self.ensure_external_class(&crate::sym::join_scope(class_name, "ClassMethods"));
    }

    fn ensure_external_class_in_scope(&mut self, scope_class: &str, raw_name: &str) {
        let raw = raw_name.trim_scope_prefix();
        if raw.is_empty() {
            return;
        }
        let mut scope = scope_class;
        loop {
            if !scope.is_empty() {
                let candidate = crate::sym::join_scope(scope, raw);
                if candidate != scope_class {
                    self.ensure_external_class(&candidate);
                    if self
                        .registry
                        .class_data_for(&candidate)
                        .is_some_and(ClassData::has_type_substance)
                    {
                        return;
                    }
                }
            }
            match scope.rfind_scope_sep() {
                Some(idx) => scope = &scope[..idx],
                None => break,
            }
        }
        self.ensure_external_class(raw);
    }

    fn is_sorbet_runtime_module(class_name: &str) -> bool {
        matches!(class_name, "T::Sig" | "T::Helpers" | "T::Generic")
    }

    fn synthesize_sorbet_runtime_module(&mut self, class_name: &str) {
        let methods: &[&str] = match class_name {
            "T::Sig" => &["sig"],
            "T::Helpers" => &[
                "abstract!",
                "interface!",
                "final!",
                "sealed!",
                "mixes_in_class_methods",
                "requires_ancestor",
            ],
            "T::Generic" => &["type_member", "type_template"],
            _ => return,
        };
        self.registry.set_is_module(class_name, true);
        for name in methods {
            self.registry.add_method_def_if_missing(
                class_name,
                MethodDef {
                    name: Sym::new(*name),
                    param_infos: Vec::new(),
                    raw_return_type: Type::Untyped,
                    sorbet_modifier_comments: Vec::new(),
                    rbs_annotated: false,
                    rbs_inline_annotated: false,
                    sig_annotated: false,
                    attr_ivar: None,
                    is_singleton: false,
                    rbs_file_source: false,
                    synthetic_dsl_source: true,
                    rbs_method_types: Default::default(),
                    extra_overloads: Vec::new(),
                    loc: None,
                },
            );
        }
    }

