    #[test]
    fn visibility_collects_bare_private_section_for_instance_methods() {
        let source = concat!(
            "class A\n",
            "  def visible = 1\n",
            "  private\n",
            "  def hidden = 2\n",
            "  public\n",
            "  def visible_again = 3\n",
            "end\n",
        );
        let registry = analyze_visibility_registry(source);
        assert_eq!(registry.method_visibility("A", "visible", false), None);
        assert_eq!(
            registry.method_visibility("A", "hidden", false),
            Some(Visibility::Private)
        );
        assert_eq!(
            registry.method_visibility("A", "visible_again", false),
            None
        );
    }

