    #[test]
    fn visibility_rendered_output_roundtrips_through_rbs_parser() {
        let source = concat!(
            "class A\n",
            "  def public_method = 1\n",
            "  private def secret = 2\n",
            "  private\n",
            "  def bare_private = 3\n",
            "  protected\n",
            "  def guarded = 4\n",
            "  public\n",
            "  def public_again = 5\n",
            "  private_class_method def self.secret_class = 6\n",
            "  def self.shown_class = 7\n",
            "end\n",
        );
        let registry = analyze_visibility_registry(source);
        let rendered = crate::rbs::render::render_rbs(&registry);
        assert!(
            rendered.contains("private def secret: -> 2"),
            "inline private def missing: {rendered}"
        );
        assert!(
            rendered.contains("private def bare_private: -> 3"),
            "bare private section missing: {rendered}"
        );
        assert!(
            rendered.contains("private def guarded: -> 4"),
            "protected collapses to private: {rendered}"
        );
        assert!(
            rendered.contains("def public_again: -> 5"),
            "public section must drop modifier: {rendered}"
        );
        assert!(
            rendered.contains("private def self.secret_class: -> 6"),
            "private singleton missing: {rendered}"
        );
        assert!(
            rbs_sys::parse_signature(&rendered).is_ok(),
            "rendered RBS must parse: {rendered}"
        );
    }

    #[test]
    fn test_module_function_keeps_singleton_signature_in_sync() {
        let source = concat!(
            "module Helper\n",
            "  module_function\n",
            "\n",
            "  def extract_user_id_from_scopes(scopes)\n",
            "    matches = scopes.grep(/\\Auser:(\\d+)\\z/)\n",
            "    return unless matches.length == 1\n",
            "\n",
            "    matches[0][/\\Auser:(\\d+)\\z/, 1].to_i\n",
            "  end\n",
            "end\n",
        );
        let core_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
        let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);
        let registry =
            crate::parser::analyze_source_with_file_path(source, None, &loader, "lib/helper.rb");
        let instance_sig = registry
            .lookup_method_sig_exact("Helper", "extract_user_id_from_scopes", false)
            .expect("instance module_function sig");
        let singleton_sig = registry
            .lookup_method_sig_exact("Helper", "extract_user_id_from_scopes", true)
            .expect("singleton module_function sig");

        assert_eq!(instance_sig.return_type.to_string(), "Integer?");
        assert_eq!(singleton_sig.return_type.to_string(), "Integer?");
    }

    #[test]
    fn test_integer_literal_handles_i64_min_and_out_of_range_values() {
        let source = concat!(
            "class Limits\n",
            "  def self.min_value\n",
            "    -9223372036854775808\n",
            "  end\n",
            "\n",
            "  def self.too_big\n",
            "    9223372036854775808\n",
            "  end\n",
            "end\n",
        );
        let core_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
        let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);
        let registry = crate::parser::analyze_source_with_file_path(
            source,
            None,
            &loader,
            "app/models/limits.rb",
        );
        let min_sig = registry
            .lookup_method_sig_exact("Limits", "min_value", true)
            .expect("min_value sig");
        let too_big_sig = registry
            .lookup_method_sig_exact("Limits", "too_big", true)
            .expect("too_big sig");

        assert_eq!(min_sig.return_type.to_string(), "-9223372036854775808");
        assert_eq!(too_big_sig.return_type.to_string(), "Integer");
    }

    #[test]
    fn test_forwardable_in_singleton_class_stays_singleton() {
        let source = concat!(
            "module Edition\n",
            "  def self.root = \"root\"\n",
            "end\n",
            "\n",
            "module Gitlab\n",
            "  class << self\n",
            "    extend Forwardable\n",
            "    def_delegators :Edition, :root\n",
            "  end\n",
            "end\n",
        );
        let core_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
        let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);
        let registry =
            crate::parser::analyze_source_with_file_path(source, None, &loader, "lib/gitlab.rb");
        let sig = registry
            .lookup_method_sig_exact("Gitlab", "root", true)
            .expect("singleton forwardable sig");

        assert_eq!(sig.return_type.to_string(), "\"root\"");
        assert!(
            registry
                .lookup_method_sig_exact("Gitlab", "root", false)
                .is_none(),
            "singleton forwardable helper should not leak into instance methods"
        );
    }

