    #[test]
    fn test_nested_class_location() {
        let source = "class Outer\n  class Inner\n    def foo\n    end\n  end\nend\n";
        let registry = crate::parser::analyze_source(source);
        let classes = registry.build_classes();

        let outer = classes
            .iter()
            .find(|c| c.name == "Outer")
            .expect("Outer class");
        let outer_loc = outer.loc.expect("Outer should have location");
        assert_eq!(outer_loc.line, 1);

        let inner = classes
            .iter()
            .find(|c| c.name == "Outer::Inner")
            .expect("Inner class");
        let inner_loc = inner.loc.expect("Inner should have location");
        assert_eq!(inner_loc.line, 2);
        assert_eq!(inner_loc.column, 2);

        let foo = inner
            .methods
            .iter()
            .find(|m| m.name == "foo")
            .expect("foo method");
        let foo_loc = foo.loc.expect("foo should have location");
        assert_eq!(foo_loc.line, 3);
    }

    #[test]
    fn test_attr_reader_location() {
        let source = "class A\n  attr_reader :x\n  attr_accessor :y\n  attr_writer :z\n  attr :legacy\nend\n";
        let registry = crate::parser::analyze_source(source);
        let classes = registry.build_classes();
        let a = classes.iter().find(|c| c.name == "A").expect("A class");

        let x_reader = a.methods.iter().find(|m| m.name == "x").expect("x reader");
        let x_loc = x_reader.loc.expect("attr_reader should have location");
        assert_eq!(x_loc.line, 2);
        assert_eq!(x_loc.column, 15);

        let y_reader = a.methods.iter().find(|m| m.name == "y").expect("y reader");
        let y_loc = y_reader
            .loc
            .expect("attr_accessor reader should have location");
        assert_eq!(y_loc.line, 3);
        assert_eq!(y_loc.column, 17);

        let y_writer = a.methods.iter().find(|m| m.name == "y=").expect("y writer");
        let y_w_loc = y_writer
            .loc
            .expect("attr_accessor writer should have location");
        assert_eq!(y_w_loc.line, 3);
        assert_eq!(y_w_loc.column, 17);

        let z_writer = a.methods.iter().find(|m| m.name == "z=").expect("z writer");
        let z_w_loc = z_writer
            .loc
            .expect("attr_writer writer should have location");
        assert_eq!(z_w_loc.line, 4);
        assert_eq!(z_w_loc.column, 15);

        let legacy_reader = a
            .methods
            .iter()
            .find(|m| m.name == "legacy")
            .expect("legacy reader");
        let legacy_loc = legacy_reader.loc.expect("attr reader should have location");
        assert_eq!(legacy_loc.line, 5);
        assert_eq!(legacy_loc.column, 8);
    }

