    #[test]
    fn test_rbs_external_has_no_location() {
        let source = "class A\n  def run\n    B.new.x\n  end\nend\n";
        let rbs_source = "class B\n  def x: -> String\nend\n";
        let mut rbs_reg = crate::registry::TypeRegistry::new();
        crate::rbs::import::load_rbs_string(rbs_source, &mut rbs_reg);
        let registry = crate::parser::analyze_source_with_rbs(source, &rbs_reg);
        let classes = registry.build_classes();

        let b = classes.iter().find(|c| c.name == "B");
        if let Some(b_class) = b {
            for m in &b_class.methods {
                if m.rbs_file_source {
                    assert!(m.loc.is_none(), "RBS-loaded method should have no location");
                }
            }
        }

        let a = classes.iter().find(|c| c.name == "A").expect("A class");
        let run = a
            .methods
            .iter()
            .find(|m| m.name == "run")
            .expect("run method");
        assert!(
            run.loc.is_some(),
            "Ruby-defined method should have location"
        );
    }

