    #[test]
    fn test_methods_for_file_excludes_other_files() {
        let source1 = "class A\n  def x\n  end\nend\n";
        let source2 = "class B\n  def y\n  end\nend\n";
        let core_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
        let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);

        let reg1 = crate::parser::analyze_source_with_file_path(source1, None, &loader, "a.rb");
        let reg2 =
            crate::parser::analyze_source_with_file_path(source2, Some(&reg1), &loader, "b.rb");

        let methods_a = reg2.methods_for_file("a.rb");
        let methods_b = reg2.methods_for_file("b.rb");

        assert!(
            methods_a.is_empty() || methods_a.iter().all(|(_, m)| m.name != "y"),
            "a.rb should not contain B#y"
        );
        assert_eq!(methods_b.len(), 1);
        assert_eq!(methods_b[0].1.name, "y");
    }

    #[test]
    fn test_methods_for_file_sorted_by_line() {
        let source = concat!(
            "class Z\n",
            "  def zebra\n  end\n",
            "  def alpha\n  end\n",
            "  def middle\n  end\n",
            "end\n",
        );
        let core_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
        let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);
        let registry = crate::parser::analyze_source_with_file_path(source, None, &loader, "z.rb");
        let methods = registry.methods_for_file("z.rb");
        assert_eq!(methods.len(), 3);
        assert_eq!(methods[0].1.name, "zebra");
        assert_eq!(methods[1].1.name, "alpha");
        assert_eq!(methods[2].1.name, "middle");
        for w in methods.windows(2) {
            assert!(w[0].1.loc.unwrap().line < w[1].1.loc.unwrap().line);
        }
    }

