    #[test]
    fn test_hover_self_method_fact_invalidated_by_backing_ivar_write() {
        let source = concat!(
            "class Corporation\n",
            "end\n",
            "class A\n",
            "  #: -> Corporation?\n",
            "  def corporation\n",
            "    @corporation\n",
            "  end\n",
            "  def process\n",
            "    return if corporation.blank?\n",
            "    @corporation = nil\n",
            "    corporation\n",
            "  end\n",
            "end\n",
        );
        let core_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
        let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);
        let result = crate::parser::hover_at(source, None, &loader, "test.rb", 11, 4);
        assert!(result.is_some(), "hover should find 'corporation'");
        let hover = result.unwrap();
        assert_eq!(hover.name, "corporation");
        // Writing to the backing ivar discards the reader's fact and reverts to the declared type. Since the link between the reader and the ivar is statically unknown, we err conservative (discard all method-name facts).
        assert_eq!(hover.ty.to_string(), "Corporation?");
    }

