    #[test]
    fn test_hover_instance_of_module_does_not_narrow() {
        // instance_of? on a namespace module can't be narrowed to a class, so we don't narrow it (collapsing to the Class type of the module's name would leave every method unresolved).
        let source = concat!(
            "module Wrapper\n",
            "end\n",
            "class A\n",
            "  #: (String | Integer) -> void\n",
            "  def a(x)\n",
            "    if x.instance_of?(Wrapper)\n",
            "      x\n",
            "    end\n",
            "  end\n",
            "end\n",
        );
        let core_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
        let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);
        let result = crate::parser::hover_at(source, None, &loader, "test.rb", 7, 6);
        assert!(result.is_some(), "hover should find 'x'");
        let hover = result.unwrap();
        assert_eq!(hover.name, "x");
        assert_eq!(hover.ty.to_string(), "Integer | String");
    }

