    #[test]
    fn test_hover_predicate_literal_return_narrows_union_then_else() {
        let source = concat!(
            "class Admin\n",
            "  #: -> true\n",
            "  def admin? = true\n",
            "end\n",
            "class Guest\n",
            "  #: -> false\n",
            "  def admin? = false\n",
            "end\n",
            "class A\n",
            "  #: (Admin | Guest) -> void\n",
            "  def a(x)\n",
            "    if x.admin?\n",
            "      x\n",
            "    else\n",
            "      x\n",
            "    end\n",
            "  end\n",
            "end\n",
        );
        let core_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
        let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);
        let then_hover = crate::parser::hover_at(source, None, &loader, "test.rb", 13, 6).unwrap();
        assert_eq!(then_hover.name, "x");
        assert_eq!(then_hover.ty.to_string(), "Admin");
        let else_hover = crate::parser::hover_at(source, None, &loader, "test.rb", 15, 6).unwrap();
        assert_eq!(else_hover.name, "x");
        assert_eq!(else_hover.ty.to_string(), "Guest");
    }

