    #[test]
    fn test_code_lens_format() {
        let source = concat!(
            "class A\n",
            "  def add(a, b)\n",
            "    a + b\n",
            "  end\n",
            "end\n",
        );
        let core_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
        let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);
        let registry =
            crate::parser::analyze_source_with_file_path(source, None, &loader, "calc.rb");
        let methods = registry.methods_for_file("calc.rb");
        assert_eq!(methods.len(), 1);
        let (class_name, sig) = &methods[0];
        assert_eq!(class_name, "A");
        assert_eq!(sig.name, "add");
        assert!(sig.loc.is_some());
        let lens_text = crate::rbs::display::format_method_sig_for_lens(sig);
        assert!(
            lens_text.contains("->"),
            "CodeLens text should contain '->'"
        );
    }

    #[test]
