    #[test]
    fn test_file_deps_superclass_reference() {
        let source = "class Admin < User\nend\n";
        let (_registry, deps) =
            crate::parser::analyze_source_with_deps(source, None, None, Some("admin.rb"));
        assert!(
            deps.defined_symbols.contains("Admin"),
            "should define Admin"
        );
        assert!(
            deps.referenced_symbols.contains("User"),
            "should reference User via superclass"
        );
    }

    #[test]
    fn test_file_deps_mixin_reference() {
        let source = concat!(
            "class Controller\n",
            "  include Auth\n",
            "  extend Logger\n",
            "  prepend Cache\n",
            "end\n",
        );
        let (_registry, deps) =
            crate::parser::analyze_source_with_deps(source, None, None, Some("ctrl.rb"));
        assert!(deps.referenced_symbols.contains("Auth"));
        assert!(deps.referenced_symbols.contains("Logger"));
        assert!(deps.referenced_symbols.contains("Cache"));
    }

