    #[test]
    fn test_hover_performance() {
        for method_count in [200, 1000] {
            let mut source = String::from("class BigApp\n");
            for i in 0..method_count {
                source.push_str(&format!("  def method_{i}(x)\n    x.to_s\n  end\n"));
            }
            let call_line = method_count * 3 + 3;
            source.push_str(&format!("end\nBigApp.new.method_{}\n", method_count / 2));
            let core_dir =
                std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
            let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);
            let expected =
                crate::parser::hover_at(&source, None, &loader, "test.rb", call_line, 12);
            assert!(
                expected.is_some(),
                "hover should resolve the generated method call"
            );

            let start = std::time::Instant::now();
            let iterations = 20;
            for _ in 0..iterations {
                let _ = crate::parser::hover_at(&source, None, &loader, "test.rb", call_line, 12);
            }
            let elapsed = start.elapsed();
            let per_call_us = elapsed.as_micros() / iterations as u128;
            let lines = source.lines().count();
            eprintln!(
                "hover_at: {iterations} calls in {:.1}ms, {per_call_us}µs/call ({lines} lines, {method_count} methods)",
                elapsed.as_secs_f64() * 1000.0,
            );
            let running_on_github_actions = std::env::var_os("GITHUB_ACTIONS").is_some();
            let max_per_call_us = if method_count >= 1000 {
                if running_on_github_actions {
                    // GitHub Actions runners have high variance;
                    300_000
                } else {
                    // This debug-build guard runs inside the full test suite, so keep it loose enough to avoid machine-load flakes while still catching major regressions.
                    200_000
                }
            } else {
                100_000
            };
            if std::env::var_os("TYDA_STRICT_PERF_TESTS").is_some() {
                assert!(
                    per_call_us < max_per_call_us,
                    "hover_at should be under {max_per_call_us}µs per call, got {per_call_us}µs"
                );
            } else if per_call_us >= max_per_call_us {
                eprintln!(
                    "hover_at exceeded report-only threshold: expected < {max_per_call_us}µs per call, got {per_call_us}µs"
                );
            }
        }
    }

    #[test]
    fn test_file_deps_self_defined_not_in_references() {
        let source = "class Foo\nend\nclass Bar < Foo\nend\n";
        let (_registry, deps) =
            crate::parser::analyze_source_with_deps(source, None, None, Some("f.rb"));
        assert!(deps.defined_symbols.contains("Foo"));
        assert!(deps.defined_symbols.contains("Bar"));
        assert!(
            !deps.referenced_symbols.contains("Foo"),
            "Foo is defined in the same file, should not be in references"
        );
    }

    #[test]
    fn extracts_sorbet_class_type_params_from_preceding_comment() {
        let dir = tempfile::tempdir().expect("tempdir");
        std::fs::create_dir_all(dir.path().join("sorbet")).expect("mkdir sorbet");
        std::fs::write(dir.path().join("sorbet/config"), ".\n").expect("write sorbet/config");
        let source = "\
# @requires_ancestor: ::Kernel
#: [out Elem]
class Box
  #: -> Elem
  def first
  end
end
";
        let core_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
        let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);
        let file_path = dir.path().join("box.rb");
        std::fs::write(&file_path, source).expect("write box.rb");
        let registry = crate::parser::analyze_source_with_file_path(
            source,
            None,
            &loader,
            file_path.to_str().expect("utf8 path"),
        );
        assert_eq!(registry.get_class_type_params("Box"), ["Elem"]);
    }

