    #[test]
    fn supports_requires_ancestor_comment_for_module_lookup() {
        let dir = tempfile::tempdir().expect("tempdir");
        std::fs::create_dir_all(dir.path().join("sorbet")).expect("mkdir sorbet");
        std::fs::write(dir.path().join("sorbet/config"), ".\n").expect("write sorbet/config");
        let source = "\
class Core
  #: -> String
  def helper = \"\"
end

# @requires_ancestor: ::Core
module NeedsCore
  def value
    helper
  end
end
";
        let core_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vendor/rbs/core");
        let loader = crate::rbs::stdlib_loader::LazyRbsLoader::new(core_dir);
        let file_path = dir.path().join("needs_core.rb");
        std::fs::write(&file_path, source).expect("write needs_core.rb");
        let registry = crate::parser::analyze_source_with_file_path(
            source,
            None,
            &loader,
            file_path.to_str().expect("utf8 path"),
        );
        assert_eq!(registry.get_required_ancestors("NeedsCore").len(), 1);
        assert_eq!(
            registry.lookup_method_return_type("NeedsCore", "value"),
            Some(Type::String)
        );
    }
